const [ph, dump] = await Promise.all([
  tools.pwsh({ description: "dsh plugin help", command: `dsh plugin --help 2>&1 | Out-String -Width 200`, timeoutMs: 90000 }),
  tools.pwsh({ description: "dump composed config", command: `dsh --profile desktop --dump-config 2>&1 | Out-String -Width 300`, timeoutMs: 180000 }),
]);
console.log("PLUGIN HELP:\n" + (ph.kind==="foreground"?(ph.stdout.text+ph.stderr.text).slice(0,2000):""));
const d = dump.kind==="foreground" ? dump.stdout.text+dump.stderr.text : "";
console.log("DUMP len:", d.length);
console.log(d.slice(0, 1500));
const r2 = await tools.pwsh({ description: "grep dump for ids", command: `dsh --profile desktop --dump-config 2>&1 | Select-String -Pattern 'experimental|agent-team|terminal|session-search|cot-translation|worktree|market' | Select-Object -First 40 | Out-String -Width 200`, timeoutMs: 180000 });
console.log("GREP:\n" + (r2.kind==="foreground"? r2.stdout.text.slice(0,2500):""));
